#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>

using namespace std;

const int INF = 1e9;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, k, c;
    if (!(cin >> n >> k >> c)) return 0;

    vector<int> a(n + 1);
    vector<int> pref(n + 1, 0);
    long long total_sum = 0;

    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
        pref[i] = pref[i - 1] + a[i];
        total_sum += a[i];
    }

    // dp[i] armazenará o menor custo de cobrir usando 'step' etiquetas até o índice i
    vector<int> dp(n + 1, 0);
    vector<int> next_dp(n + 1, INF);

    for (int step = 1; step <= k; ++step) {
        int min_i = step * c;
        int max_i = n - (k - step) * c;

        next_dp[min_i] = dp[min_i - c] + (pref[min_i] - pref[min_i - c]);
        for (int i = min_i + 1; i <= max_i; ++i) {
            int cover_here = dp[i - c] + (pref[i] - pref[i - c]);
            next_dp[i] = min(next_dp[i - 1], cover_here);
        }

        for (int i = min_i; i <= max_i; ++i) {
            dp[i] = next_dp[i];
        }
    }

    long long min_covered = dp[n];
    cout << total_sum - min_covered << "\n";

    return 0;
}
